<script setup lang="ts">
import { ref, computed } from 'vue'
const provider = ref('OpenAIOfficial'), protocol = ref('OpenAI'), key = ref(''), endpointUrl = ref(''), model = ref(''), models = ref<string[]>([]), modelError = ref(''), loadingModels = ref(false), useProxy = ref(false), result = ref(''), loading = ref(false)
const categories = [{id:'llm',name:'LLM'},{id:'api',name:'普通 API'},{id:'http',name:'HTTP'}]
const category = ref('llm')
const providers = [{id:'OpenAIOfficial',name:'OpenAI',type:'llm',protocol:'OpenAI'},{id:'Claude',name:'Claude',type:'llm',protocol:'Anthropic'},{id:'Ark',name:'方舟',type:'llm',protocol:'OpenAI'},{id:'Mimo',name:'Mimo',type:'llm',protocol:'OpenAI'},{id:'GLM',name:'GLM',type:'llm',protocol:'OpenAI'},{id:'Bocha',name:'Bocha',type:'api'},{id:'Tavily',name:'Tavily',type:'api'},{id:'Brave',name:'Brave',type:'api'},{id:'Custom',name:'自定义供应商',type:'custom'}]
const visibleProviders = computed(() => providers.filter(p => category.value === 'llm' ? p.type === 'llm' || p.type === 'custom' : p.type === 'api'))
const selected = computed(() => providers.find(p => p.id === provider.value)!), isLlm = computed(() => selected.value?.type === 'llm' || selected.value?.type === 'custom'), needsCustomUrl = computed(() => provider.value === 'Custom')
async function loadModels() { if (!isLlm.value || !key.value.trim() || (needsCustomUrl.value && !endpointUrl.value.trim())) { models.value = []; model.value = ''; return } loadingModels.value = true; modelError.value = ''; try { const r = await fetch('/api/models', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ provider: provider.value, protocol: protocol.value, key: key.value, endpointUrl: needsCustomUrl.value ? endpointUrl.value : null, useProxy: useProxy.value }) }); if (!r.ok) throw new Error(await r.text()); models.value = (await r.json()).models ?? []; model.value = models.value[0] ?? ''; if (!model.value) throw new Error('模型列表为空') } catch (e) { models.value = []; model.value = ''; modelError.value = e instanceof Error ? e.message : '模型获取失败，可手动填写' } finally { loadingModels.value = false } }
function select(p: typeof providers[number]) { provider.value = p.id; if (p.protocol) protocol.value = p.protocol; loadModels() }
function selectCategory(id: string) { category.value = id; result.value = ''; if (id === 'http') return; const first = providers.find(p => id === 'llm' ? p.type === 'llm' : p.type === 'api'); if (first) select(first) }
async function check() { if (category.value !== 'http' && isLlm.value && !model.value.trim()) { result.value = '请先获取并选择模型'; return } loading.value = true; result.value = ''; try { const http = category.value === 'http'; const r = await fetch(http ? '/api/http-check' : '/api/public-check', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(http ? { url: endpointUrl.value.trim(), useProxy: useProxy.value } : { provider: provider.value, protocol: isLlm.value ? protocol.value : null, model: isLlm.value && model.value.trim() ? model.value.trim() : null, key: key.value, endpointUrl: isLlm.value && endpointUrl.value.trim() ? endpointUrl.value.trim() : null, useProxy: useProxy.value }) }); result.value = r.ok ? JSON.stringify(await r.json(), null, 2) : await r.text() } catch (e) { result.value = e instanceof Error ? e.message : '请求失败' } finally { loading.value = false } }
</script>
<template>
  <main>
    <header><div class="logo">API<span>Monitor</span></div><span class="header-status">实时检测</span></header>
    <section class="hero">
      <p class="eyebrow">REAL-TIME API OBSERVABILITY</p>
      <h1>API 状态，一目了然</h1>
      <p class="sub">选择检测类型，快速验证服务是否正常响应。</p>
      <div class="card">
        <div class="card-intro"><div><span class="card-kicker">新建检测</span><h2>配置检测参数</h2></div><span class="secure-badge">● 安全连接</span></div>
        <div class="form-layout">
          <aside class="type-column"><div class="section-title"><span class="section-number">01</span><div><strong>检测类型</strong><small>选择要检测的服务类别</small></div></div><div class="providers type-tabs"><button v-for="c in categories" :key="c.id" :class="{active: category===c.id}" @click="selectCategory(c.id)">{{c.name}}</button></div><div class="type-note"><strong>当前模式</strong><span>{{category === 'llm' ? '真实对话与模型可用性' : category === 'api' ? '普通 API 接口连通性' : '健康检查 URL 状态码'}}</span></div></aside>
          <div class="config-column">
            <template v-if="category !== 'http'">
              <div class="form-section first-section"><div class="section-title"><span class="section-number">02</span><div><strong>服务与认证</strong><small>选择供应商并填写访问凭证</small></div></div><div class="label">供应商</div><div class="providers"><button v-for="p in visibleProviders" :key="p.id" :class="{active: provider===p.id}" @click="select(p)">{{p.name}}</button></div>
                <template v-if="isLlm"><div class="sub-fields"><div class="field"><label>协议</label><select v-model="protocol" :disabled="!needsCustomUrl" @change="loadModels"><option value="OpenAI">OpenAI</option><option value="Anthropic">Anthropic</option></select><small v-if="!needsCustomUrl">该供应商协议固定为 {{protocol}}</small></div><template v-if="needsCustomUrl"><div class="field"><label>自定义基础 URL</label><input v-model="endpointUrl" type="url" placeholder="https://your-provider.example.com/v1" maxlength="500" @change="loadModels"/><small>填写到 /v1，系统自动追加接口路径</small></div></template></div></template>
                <div class="field key-field"><label>API Key</label><input v-model="key" type="password" placeholder="粘贴你的 API Key" maxlength="512" @change="loadModels"/></div>
              </div>
              <div v-if="isLlm" class="form-section model-section"><div class="section-title"><span class="section-number">03</span><div><strong>选择模型</strong><small>用于真实对话检测的模型</small></div><span v-if="models.length" class="model-count">{{models.length}} 个可用</span></div><div class="model-controls"><select v-if="models.length" v-model="model" class="model-select"><option v-for="item in models" :key="item" :value="item">{{item}}</option></select><input v-else-if="modelError" v-model="model" class="model-select" placeholder="手动填写模型 ID" maxlength="120"/><button type="button" class="model-load" :disabled="loadingModels || !key || (needsCustomUrl && !endpointUrl)" @click="loadModels"><span class="button-icon">↻</span>{{loadingModels ? '获取中…' : (models.length ? '刷新模型' : '获取模型')}}</button></div><small class="model-status" :class="{error:modelError,success:models.length && !modelError}"><span class="status-dot"></span>{{modelError || (models.length ? '模型列表已加载，可直接选择' : '填写 API Key 后自动获取模型列表')}}</small></div>
            </template>
            <template v-else><div class="form-section first-section"><div class="section-title"><span class="section-number">02</span><div><strong>检测地址</strong><small>发送 GET 请求，仅 HTTP 200 判定为成功</small></div></div><div class="field"><label>目标 URL</label><input v-model="endpointUrl" type="url" placeholder="https://example.com/health" maxlength="500"/><small>不跟随重定向，适合检测健康检查接口。</small></div></div></template>
            <div class="advanced-row"><label class="proxy-toggle"><span class="toggle-control"><input v-model="useProxy" type="checkbox" @change="category !== 'http' && isLlm && loadModels()"/><span class="toggle-slider"></span></span><span><strong>使用服务端代理</strong><small>通过服务器网络访问目标服务</small></span></label><span class="proxy-hint">{{useProxy ? '已开启' : '未开启'}}</span></div>
            <button class="check" :disabled="loading || (category === 'http' ? !endpointUrl.trim() : !key || (isLlm && !model))" @click="check"><span>{{loading ? '正在检测…' : '开始真实检测'}}</span><b>→</b></button>
            <div v-if="result" class="result-panel"><div class="result-title">检测结果</div><pre>{{result}}</pre></div>
          </div>
        </div>
      </div>
    </section>
  </main>
</template>
